<?php
require_once '../config/auth.php';require_role('admin');$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='status'){$q=$pdo->prepare('UPDATE users SET status=? WHERE id_user=?');$q->execute([$_POST['status'],(int)$_POST['id_user']]);flash('success','Status akun diperbarui.');}elseif($action==='reset'){$q=$pdo->prepare('UPDATE users SET password=? WHERE id_user=?');$q->execute([password_hash('password',PASSWORD_BCRYPT),(int)$_POST['id_user']]);flash('success','Password direset menjadi password.');}else{if(strlen($_POST['password']??'')<8)throw new InvalidArgumentException('Password minimal 8 karakter.');$q=$pdo->prepare('INSERT INTO users(username,password,role,id_referensi,status) VALUES(?,?,?,?,?)');$q->execute([trim($_POST['username']),password_hash($_POST['password'],PASSWORD_BCRYPT),$_POST['role'],trim($_POST['id_referensi']??'')?:null,'aktif']);flash('success','Akun berhasil dibuat.');}redirect('users.php');}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){$error='Gagal memproses akun. Username mungkin sudah digunakan.';}}
$rows=$pdo->query('SELECT id_user,username,role,id_referensi,status,created_at FROM users ORDER BY id_user DESC')->fetchAll();$page_title='Manajemen Akun';require '../includes/header.php';require '../includes/sidebar.php';require '../includes/flash.php';
?><h2>Manajemen Akun</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-4 mb-4"><h5 class="mb-3">Buat akun baru</h5><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="add"><div class="col-md-3"><label class="form-label">Username</label><input class="form-control" name="username" required></div><div class="col-md-3"><label class="form-label">Password</label><input class="form-control" type="password" name="password" minlength="8" required></div><div class="col-md-2"><label class="form-label">Role</label><select class="form-select" name="role"><option value="admin">Admin</option><option value="guru">Guru</option><option value="kepala_sekolah">Kepala Sekolah</option><option value="siswa">Siswa</option></select></div><div class="col-md-2"><label class="form-label">ID referensi</label><input class="form-control" name="id_referensi" placeholder="ID guru / NIS"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Buat akun</button></div></form></div><div class="card p-3"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Username</th><th>Role</th><th>Referensi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['username'])?></td><td><?=e(role_label($r['role']))?></td><td><?=e($r['id_referensi']??'-')?></td><td><span class="badge text-bg-<?=$r['status']==='aktif'?'success':'secondary'?>"><?=e($r['status'])?></span></td><td class="text-nowrap"><form method="post" class="d-inline"><?=csrf_field()?><input type="hidden" name="action" value="reset"><input type="hidden" name="id_user" value="<?=$r['id_user']?>"><button class="btn btn-sm btn-outline-warning">Reset</button></form><form method="post" class="d-inline"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id_user" value="<?=$r['id_user']?>"><input type="hidden" name="status" value="<?=$r['status']==='aktif'?'nonaktif':'aktif'?>"><button class="btn btn-sm btn-outline-<?=$r['status']==='aktif'?'danger':'success'?>"><?=$r['status']==='aktif'?'Nonaktifkan':'Aktifkan'?></button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require '../includes/footer.php';
